let currentLang = "es";

export function getLang() {
  return currentLang;
}

export function setLang(lang) {
  currentLang = lang === "en" ? "en" : "es";
  return currentLang;
}

export const T = (k) => (STR[currentLang] && STR[currentLang][k]) || STR.es[k] || k;
export { STR };
